function filteredAssets() {
  const query = assetSearch.value.trim().toLowerCase();
  return ASSETS.filter((asset) => {
    const matchesPurpose = activePurpose === "全部用途" || assetPurpose(asset) === activePurpose;
    const matchesPackage = activePackage === "全部" || asset.package === activePackage;
    const matchesCategory = activeCategory === "全部" || asset.category === activeCategory;
    const haystack = `${asset.name} ${asset.id} ${asset.category} ${asset.package} ${assetPurpose(asset)}`.toLowerCase();
    const matchesSearch = !query || haystack.includes(query);
    return matchesPurpose && matchesPackage && matchesCategory && matchesSearch;
  });
}

function renderAssetList() {
  const assets = filteredAssets();
  assetList.innerHTML = "";
  for (const asset of assets) {
    const card = document.createElement("button");
    card.type = "button";
    card.className = `asset-card${selectedAsset && asset.id === selectedAsset.id ? " active" : ""}`;
    card.draggable = true;
    card.title = `${assetPurpose(asset)} / ${asset.package} / ${asset.category} / ${asset.name}`;
    card.setAttribute("aria-label", card.title);
    card.innerHTML = `
      <img src="${assetUrl(asset)}" alt="${asset.name}" loading="lazy">
      <span>${asset.name}</span>
    `;
    card.addEventListener("click", () => selectAsset(asset));
    card.addEventListener("dragstart", (event) => {
      selectAsset(asset);
      event.dataTransfer.setData("text/plain", asset.id);
      event.dataTransfer.effectAllowed = "copy";
    });
    assetList.appendChild(card);
  }
  statusText.textContent = `用途：${activePurpose}；当前显示 ${assets.length} / ${assets.length}，总计 ${ASSETS.length} 个素材。`;
}

function selectAsset(asset) {
  selectedAsset = asset;
  selectedStampId = null;
  selectionLabel.textContent = `当前选择：${asset.name}`;
  statusText.textContent = asset.id === GROUND_ASSET_ID ? "草地是固定底层；点击铺草不会覆盖已有素材。" : "点击或拖拽到网格可放置覆盖素材，素材会叠加在草地底层之上。";
  renderAssetList();
  renderStamps();
}



