func _projectile_hits_blocked_cell(from_pos: Vector2, to_pos: Vector2) -> bool:
	var steps: int = max(1, int(ceil(from_pos.distance_to(to_pos) / max(4.0, active_cell_px * 0.25))))
	for i in range(steps + 1):
		var t := float(i) / float(steps)
		var pos := from_pos.lerp(to_pos, t)
		var cell := Vector2i(int(floor(pos.x / active_cell_px)), int(floor(pos.y / active_cell_px)))
		if active_blocked_cells.has(cell):
			return true
	return false

