func _find_actor_in_facing_direction(max_range: float, half_width: float) -> Dictionary:
	if player == null:
		return {}
	var origin: Vector2 = player.global_position
	var direction := _facing_vector()
	var best: Dictionary = {}
	var best_forward := INF
	for npc in active_npcs:
		if typeof(npc) != TYPE_DICTIONARY:
			continue
		var target_pos: Vector2 = _actor_position(npc)
		var offset: Vector2 = target_pos - origin
		var forward: float = offset.dot(direction)
		if forward < 0.0 or forward > max_range:
			continue
		var lateral: float = abs(offset.cross(direction))
		if lateral <= half_width and forward < best_forward:
			best = npc
			best_forward = forward
	return best

func _find_actor_near_line(from_pos: Vector2, to_pos: Vector2, half_width: float) -> Dictionary:
	var segment: Vector2 = to_pos - from_pos
	var length_sq: float = segment.length_squared()
	if length_sq <= 0.01:
		return {}
	for npc in active_npcs:
		if typeof(npc) != TYPE_DICTIONARY:
			continue
		var target_pos: Vector2 = _actor_position(npc)
		var t: float = clamp((target_pos - from_pos).dot(segment) / length_sq, 0.0, 1.0)
		var closest: Vector2 = from_pos + segment * t
		if closest.distance_to(target_pos) <= half_width:
			return npc
	return {}

