const fs=require('fs');
const code=fs.readFileSync('web/game.js','utf8');
const manifest=JSON.parse(fs.readFileSync('assets/game/kenney-map-library/manifest.json','utf8'));
const EDITOR_PACKAGE_PREFIXES=["tiny-","favorite-","ai-"];
const EDITOR_EXCLUDED_PACKAGES=new Set(["favorite-tower-defense","tower-defense-top-down"]);
const assets=(manifest.assets||[]).filter(a=>EDITOR_PACKAGE_PREFIXES.some(p=>a.package.startsWith(p))&&!EDITOR_EXCLUDED_PACKAGES.has(a.package));
function tileNum(asset){return Number(((asset.id||'').toLowerCase().match(/(?:tile|maptile)_(\d+)/)||[])[1]);}
const grass=[];
for(const a of assets){
 const text=`${a.package} ${a.category} ${a.id} ${a.name}`.toLowerCase();
 const path=a.id.toLowerCase();
 const n=tileNum(a);
 let reason='';
 if((a.mode==='tile'||/\/tiles?\//.test(path)||/maptile_\d+/.test(path)) && /ground|terrain|floor|grass|dirt|soil|sand|snow|ice|mud|desert|land|field|tile[-_ ]?grass|tile[-_ ]?sand|地面|地形|草地|泥地|沙地|雪地|冰面|土地/.test(text)) reason='early-ground-text';
 else if(a.package==='favorite-map-pack' && Number.isFinite(n) && n>=1 && n<=40) reason='favorite-map-pack-1-40';
 else if(a.package==='favorite-pixel-platformer' && /\/tiles\/grass\//.test(path)) reason='pixel-platformer-grass';
 else if(a.package==='favorite-tiny-battle' && Number.isFinite(n) && n<=17) reason='tiny-battle-<=17';
 else if(a.package==='favorite-rpg-urban-pack' && Number.isFinite(n) && n>=27 && n<=49) reason='rpg-urban-27-49';
 else if(/ground|terrain|floor|grass|dirt|soil|sand|snow|ice|mud|desert|land|field|tile[-_ ]?grass|tile[-_ ]?sand|地面|地形|草地|泥地|沙地|雪地|冰面|土地/.test(text) || a.mode==='tile') reason='fallback-ground-or-tile';
 if(reason){
   // simulate groundPurposeFromText
   let purpose='地面-草地';
   if(/snow|ice|ski|winter|frozen|雪|冰/.test(text)) purpose='地面-雪地';
   else if(/desert|sand|beach|dune|沙漠|沙地|沙滩/.test(text)) purpose='地面-沙漠';
   else if(/mud|dirt|soil|泥|土/.test(text)) purpose='地面-泥地沙地';
   if(reason==='favorite-map-pack-1-40'||reason==='pixel-platformer-grass'||reason==='tiny-battle-<=17'||reason==='rpg-urban-27-49') purpose='地面-草地';
   if(purpose==='地面-草地') grass.push({pkg:a.package,id:a.id,name:a.name,cat:a.category,mode:a.mode,reason});
 }
}
const byPkg={}; for(const g of grass){(byPkg[g.pkg]??=[]).push(g)}
for(const [pkg,arr] of Object.entries(byPkg).sort()){
 console.log('\n##',pkg,arr.length);
 for(const g of arr.slice(0,80)) console.log(g.reason,'|',g.id,'|',g.name,'|',g.cat,'|',g.mode);
}
