	return true

func _player_blocks_npc_cell(cell: Vector2i) -> bool:
	if player == null:
		return false
	return _world_to_npc_cell(player.position) == cell

func _other_npc_blocks_cell(cell: Vector2i, npc: Dictionary) -> bool:
	var uid := int(npc.get("uid", -1))
	for other in active_npcs:
		if typeof(other) != TYPE_DICTIONARY:
			continue
		if int(other.get("uid", -2)) == uid:
			continue
		var body: CharacterBody2D = other.get("body", null)
		var other_pos: Vector2 = body.position if body != null else other.get("position", Vector2.ZERO)
